window.HOEREN_TESTS[33] = {"id":"im-krankenhaus","name":"Im Krankenhaus","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Krankenhaus-Information für alle Besucher: Die Besuchszeit dauert von 14 bis 19 Uhr. Bitte bringen Sie keine Blumen mit, wegen Allergien sind die in unserem Haus verboten. Auch keine warmen Speisen, kekse und Obst sind erlaubt, aber bitte fragen Sie die Pflege, ob der Patient das essen darf.","gender":"f","q":"Was ist erlaubt im Krankenhaus?","opts":["Kekse und Obst.","Blumen.","Warme Speisen."],"correct":0},{"transcript":"Hallo Frau Klein, hier ist Schwester Maria vom St. Anna Krankenhaus, ihrer Mutter geht es heute deutlich besser, die Operation war erfolgreich. Heute kommt sie noch nicht nach Hause, und in zwei Wochen wäre zu spät. Sie kann nächste Woche nach Hause, am Mittwoch. Bitte holen Sie sie um 11 Uhr ab, mit bequemer Kleidung.","gender":"f","q":"Wann kommt die Mutter nach Hause?","opts":["Nächste Woche am Mittwoch.","In zwei Wochen.","Heute."],"correct":0},{"transcript":"Achtung an alle Patienten der Station 3: Die Visite findet heute nicht um 9 Uhr wie üblich statt, und sie fällt auch nicht aus. Sie ist um 11 Uhr, weil Doktor Bauer heute Morgen einen Notfall hatte. Bitte bleiben Sie in Ihren Zimmern, bis die Schwestern Sie holen. Das Frühstück wurde schon ausgeteilt.","gender":"m","q":"Wann findet die Visite statt?","opts":["Um 9 Uhr wie üblich.","Fällt aus.","Um 11 Uhr."],"correct":2},{"transcript":"Hi Tom, hier ist Anna. Ich liege seit gestern im Krankenhaus, Blinddarm. Die Operation war heute Morgen, alles gut gelaufen. Bring mir bitte Bücher mit, wenn du kommst. Blumen darf ich nicht, und eine Mahlzeit brauche ich nicht, hier gibt es Essen. Keine Sorge, ich bin in einer Woche zu Hause. Die Schmerzmittel machen mich nur müde.","gender":"f","q":"Was möchte Anna?","opts":["Eine Mahlzeit.","Blumen.","Bücher."],"correct":2},{"transcript":"Liebe Hörer, das Stadtkrankenhaus hat ab nächstem Monat neue Notfall-Nummern. Die alte Nummer wird abgeschaltet. Bitte speichern Sie 089 555 999, das ist die neue Notfall-Hotline rund um die Uhr. Nicht alle Nummern ändern sich: Für Termine bei Sprechstunden bleibt die alte Sprechstunden-Nummer noch bis Ende des Monats gültig.","gender":"f","q":"Was ändert sich?","opts":["Sprechstunden-Nummer.","Notfall-Nummer.","Alle Nummern."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer ist wegen was im Krankenhaus? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Jens","gender":"m","text":"Hier im Flur ist es heute laut. Kennst du den Plan der Station?"},{"speaker":"Claudia","gender":"f","text":"Die Familie liegt auf zwei Etagen. Ich habe die Zimmer aufgeschrieben."},{"speaker":"Jens","gender":"m","text":"Ich hatte einen Herzinfarkt. Der Arzt sagt, dass es bei mir knapp war."},{"speaker":"Claudia","gender":"f","text":"Du bleibst noch ein paar Tage hier, Jens."},{"speaker":"Jens","gender":"m","text":"Ist jemand nur wegen Kopfschmerzen hier?"},{"speaker":"Claudia","gender":"f","text":"Nein. Kopfschmerzen hat hier keiner."},{"speaker":"Jens","gender":"m","text":"Du liegst doch auch nicht ohne Grund in diesem Bett."},{"speaker":"Claudia","gender":"f","text":"Ich habe mir das Bein gebrochen. Die Treppe im Garten war bei mir nass."},{"speaker":"Jens","gender":"m","text":"Das tut mir leid, Claudia. Lukas hustet auf Zimmer zwölf schon seit Tagen."},{"speaker":"Claudia","gender":"f","text":"Lukas hat eine Lungenentzündung. Er bekommt jeden Morgen Medizin."},{"speaker":"Jens","gender":"m","text":"Lisa liegt eine Etage höher und lächelt die ganze Zeit."},{"speaker":"Claudia","gender":"f","text":"Lisa hat ein Baby bekommen. Die Kleine heißt Mia."},{"speaker":"Jens","gender":"m","text":"Ist das bei jemandem nur eine Grippe?"},{"speaker":"Claudia","gender":"f","text":"Nein. Eine Grippe ist es auch nicht."},{"speaker":"Jens","gender":"m","text":"Ich habe vorhin noch jemanden im Aufzug gesehen."},{"speaker":"Claudia","gender":"f","text":"Bei Frank hat der Arzt Gallensteine entfernt. Die Operation war gestern."},{"speaker":"Jens","gender":"m","text":"Dann besuche ich Lukas nach dem Mittagessen."},{"speaker":"Claudia","gender":"f","text":"Geh langsam. Ich warte mit dem Tee auf dem Zimmer."}],"options":[{"letter":"a","text":"hat ein Baby bekommen"},{"letter":"b","text":"hat sich Gallensteine entfernen lassen"},{"letter":"c","text":"wurde am Knie operiert"},{"letter":"d","text":"hat Kopfschmerzen"},{"letter":"e","text":"hatte einen Herzinfarkt"},{"letter":"f","text":"hat eine Grippe"},{"letter":"g","text":"hat eine Lungenentzündung"},{"letter":"h","text":"hat sich das Bein gebrochen"},{"letter":"i","text":"ist im Krankenhaus für eine Kontrolle"}],"items":[{"person":"Jens","correct":"e"},{"person":"Claudia","correct":"h"},{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"a"},{"person":"Frank","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Krankenschwester","gender":"f","text":"Guten Morgen, wie fühlen Sie sich heute?"},{"speaker":"Patient","gender":"m","text":"Besser als gestern, aber müde. Schnitzel konnte ich nicht essen."},{"speaker":"Krankenschwester","gender":"f","text":"Haben Sie etwas gegessen? Nichts, oder doch ein bisschen?"},{"speaker":"Patient","gender":"m","text":"Etwas Suppe heute Mittag. Mein Appetit ist noch nicht zurück, aber die Suppe habe ich geschafft."},{"speaker":"Krankenschwester","gender":"f","text":"Das ist normal nach der Operation. Schnitzel gibt es erst in ein paar Tagen wieder."}],"q":"Was hat der Patient gegessen?","opts":["Schnitzel.","Nichts.","Suppe."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, welches Zimmer hat mein Mann bitte? Ich suche Zimmer 305, 503 oder 350."},{"speaker":"Sekretärin","gender":"f","text":"Wie ist der Name, bitte?"},{"speaker":"Frau","gender":"f","text":"Karl Schmidt, liegt er in Zimmer 503 oder in Zimmer 350?"},{"speaker":"Sekretärin","gender":"f","text":"Er liegt in Zimmer 305, dritter Stock. Nicht 503 und nicht 350, mit dem Aufzug rechts, dann links."},{"speaker":"Frau","gender":"f","text":"Danke, Zimmer 305, dann gehe ich gleich nach oben zu meinem Mann."}],"q":"Welches Zimmer?","opts":["503.","305.","350."],"correct":1},{"lines":[{"speaker":"Arzt","gender":"m","text":"Sie können morgen nach Hause. Heute noch nicht, wir wollen die Nacht noch beobachten."},{"speaker":"Patientin","gender":"f","text":"Schon morgen? Ich dachte, in drei Tagen noch, oder vielleicht erst heute Abend?"},{"speaker":"Arzt","gender":"m","text":"Sie haben sich schneller erholt als erwartet. Heute bleiben Sie hier, morgen geht es nach Hause, nicht in drei Tagen."},{"speaker":"Patientin","gender":"f","text":"Toll, dann sage ich meiner Schwester, sie holt mich morgen ab."},{"speaker":"Arzt","gender":"m","text":"Bitte um 10 Uhr an der Rezeption. Wir geben Ihnen die Papiere mit."}],"q":"Wann darf die Patientin nach Hause?","opts":["Heute.","In drei Tagen.","Morgen."],"correct":2},{"lines":[{"speaker":"Pflegerin","gender":"f","text":"Brauchen Sie etwas? Wasser, etwas zu essen, oder soll ich die Sonne ins Zimmer lassen?"},{"speaker":"Patient","gender":"m","text":"Ein Glas Wasser, bitte, essen möchte ich gerade nicht."},{"speaker":"Pflegerin","gender":"f","text":"Soll ich auch die Vorhänge öffnen, Sonne im Zimmer?"},{"speaker":"Patient","gender":"m","text":"Nein, die Sonne tut mir in den Augen weh. Nur Wasser, danke, kein Essen."},{"speaker":"Pflegerin","gender":"f","text":"Gut, ich bringe gleich ein Glas Wasser. Die Vorhänge bleiben zu."}],"q":"Was möchte der Patient?","opts":["Wasser.","Sonne im Zimmer.","Etwas zu essen."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, wann sind die Besuchszeiten? Den ganzen Tag, oder nur nachmittags?"},{"speaker":"Empfangsdame","gender":"f","text":"Unter der Woche 14 bis 19 Uhr, nicht den ganzen Tag."},{"speaker":"Mann","gender":"m","text":"Und am Wochenende? Auch 14 bis 19 Uhr?"},{"speaker":"Empfangsdame","gender":"f","text":"Am Wochenende länger, 11 bis 20 Uhr. Den ganzen Tag geht trotzdem nicht, nach 20 Uhr ist Ruhe."},{"speaker":"Mann","gender":"m","text":"Verstehe, dann komme ich Samstag um 11 Uhr. Danke."}],"q":"Wann sind Besuchszeiten am Wochenende?","opts":["14-19 Uhr.","11-20 Uhr.","Den ganzen Tag."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Bauer, einer Krankenschwester. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Bauer, Sie arbeiten seit 18 Jahren als Krankenschwester im St. Anna Krankenhaus. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Bauer","gender":"f","text":"Meine Großmutter war im Krankenhaus, als ich 15 war. Die Pflege dort hat mich so beeindruckt — wie ruhig und freundlich alle waren. Ich habe damals entschieden, das auch zu machen. Eigentlich wollte ich Ärztin werden, aber das Studium war zu lang."},{"speaker":"Reporter","gender":"m","text":"Wie ist Ihr typischer Arbeitstag?"},{"speaker":"Bauer","gender":"f","text":"Schichten — Frühschicht ab 6 Uhr, Spätschicht bis 22 Uhr, oder Nachtschicht. Während der Schicht: Patienten waschen, Medikamente geben, Wunden versorgen, Mahlzeiten bringen. Auch viel sprechen mit Patienten und Angehörigen."},{"speaker":"Reporter","gender":"m","text":"Was ist das schwierigste?"},{"speaker":"Bauer","gender":"f","text":"Sterbende Patienten begleiten. Auch nach 18 Jahren ist das schwer. Aber es ist auch wertvoll — wir helfen, dass jemand würdig stirbt. Manche Familien sind sehr dankbar dafür."},{"speaker":"Reporter","gender":"m","text":"Was sind die schönsten Momente?"},{"speaker":"Bauer","gender":"f","text":"Wenn ein Patient gesund nach Hause geht — vor allem nach schwerer Krankheit. Auch Geburten in der Frauenstation. Die Augen einer neuen Mutter sind das Schönste."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie nach der Arbeit?"},{"speaker":"Bauer","gender":"f","text":"Ich brauche Stille. Ich mache Yoga zu Hause, lese Bücher, höre ruhige Musik. Im Krankenhaus ist es sehr laut und stressig — privat brauche ich das Gegenteil."}],"items":[{"q":"Sie arbeitet immer in der Frühschicht.","correct":"nein"},{"q":"Frau Bauer wollte ursprünglich Ärztin werden.","correct":"ja"},{"q":"Sterbende Patienten begleiten ist mit der Zeit leichter.","correct":"nein"},{"q":"Geburten gehören zu ihren schönsten Erlebnissen.","correct":"ja"},{"q":"Nach der Arbeit liebt sie laute Musik.","correct":"nein"}]}]};
